//! E2E test client that plays the browser's role (offerer) against a running llama-connect host.
//! Flow: tracker announce with one offer -> receive answer -> data channel "tunnel" -> auth -> GET request -> print streamed response.
//! Usage: cargo run --example test_client -- <40-char share code> [path] [tracker_url]

use std::sync::Arc;
use std::time::Duration;

use base64::engine::general_purpose::STANDARD as B64;
use base64::Engine;
use futures_util::{SinkExt, StreamExt};
use tokio::sync::mpsc;
use tokio_tungstenite::connect_async;
use tokio_tungstenite::tungstenite::Message;

use webrtc::data_channel::data_channel_message::DataChannelMessage;
use webrtc::ice_transport::ice_server::RTCIceServer;
use webrtc::peer_connection::configuration::RTCConfiguration;
use webrtc::peer_connection::sdp::session_description::RTCSessionDescription;

use llama_server_connect::protocol::{self, TunnelMsg};

#[tokio::main]
async fn main() {
    env_logger::Builder::from_env(env_logger::Env::default().default_filter_or("info")).init();
    let mut args = std::env::args().skip(1);
    let share_code = protocol::ShareCode::parse(&args.next().expect("share code required")).unwrap();
    let path = args.next().unwrap_or_else(|| "/health".to_string());
    let tracker_url = args
        .next()
        .unwrap_or_else(|| "wss://tracker.openwebtorrent.com".to_string());

    let info_hash = protocol::room_to_info_hash(&share_code.room_code);
    let peer_id = protocol::random_code(20);
    let offer_id = protocol::random_code(20);

    // --- build offer with data channel, wait for ICE gathering (non-trickle)
    let api = llama_server_connect::peer::build_api();
    let pc = Arc::new(
        api.new_peer_connection(RTCConfiguration {
            ice_servers: vec![RTCIceServer {
                urls: vec!["stun:stun.l.google.com:19302".to_string()],
                ..Default::default()
            }],
            ..Default::default()
        })
        .await
        .unwrap(),
    );

    let dc = pc.create_data_channel("tunnel", None).await.unwrap();

    // route all data channel events into one place so the main flow reads top-to-bottom
    let (evt_tx, mut evt_rx) = mpsc::unbounded_channel::<Option<TunnelMsg>>();
    let open_tx = evt_tx.clone();
    dc.on_open(Box::new(move || {
        let _ = open_tx.send(None); // None = channel opened
        Box::pin(async {})
    }));
    let msg_tx = evt_tx.clone();
    dc.on_message(Box::new(move |m: DataChannelMessage| {
        if let Ok(msg) = serde_json::from_slice::<TunnelMsg>(&m.data) {
            let _ = msg_tx.send(Some(msg));
        }
        Box::pin(async {})
    }));

    let offer = pc.create_offer(None).await.unwrap();
    let mut gathered = pc.gathering_complete_promise().await;
    pc.set_local_description(offer).await.unwrap();
    let _ = tokio::time::timeout(Duration::from_secs(10), gathered.recv()).await;
    let offer_sdp = pc.local_description().await.unwrap();
    eprintln!(
        "[client] offer ready ({} candidates)",
        offer_sdp.sdp.lines().filter(|l| l.starts_with("a=candidate")).count()
    );

    // --- announce the offer on the tracker, wait for the host's answer
    let (ws, _) = connect_async(&tracker_url).await.unwrap();
    let (mut sink, mut stream) = ws.split();
    let announce = serde_json::json!({
        "action": "announce",
        "info_hash": info_hash,
        "peer_id": peer_id,
        "numwant": 1,
        "offers": [{ "offer_id": offer_id, "offer": { "type": "offer", "sdp": offer_sdp.sdp } }],
    });
    sink.send(Message::text(announce.to_string())).await.unwrap();
    eprintln!("[client] offer announced on {tracker_url}, waiting for answer...");

    let answer_sdp = loop {
        let msg = tokio::time::timeout(Duration::from_secs(30), stream.next())
            .await
            .expect("timed out waiting for answer")
            .expect("tracker closed")
            .unwrap();
        let Message::Text(txt) = msg else { continue };
        let v: serde_json::Value = serde_json::from_str(&txt).unwrap_or_default();
        if v.get("answer").is_some() && v["offer_id"] == serde_json::json!(offer_id) {
            break v["answer"]["sdp"].as_str().unwrap().to_string();
        }
    };
    eprintln!("[client] got answer, connecting...");
    pc.set_remote_description(RTCSessionDescription::answer(answer_sdp).unwrap())
        .await
        .unwrap();

    // --- drive the tunnel: open -> auth -> req -> stream response
    let mut body = Vec::new();
    let deadline = tokio::time::Instant::now() + Duration::from_secs(60);
    loop {
        let evt = tokio::time::timeout_at(deadline, evt_rx.recv())
            .await
            .expect("timed out")
            .expect("event channel closed");
        match evt {
            None => {
                eprintln!("[client] data channel open, authenticating");
                dc.send_text(
                    serde_json::to_string(&TunnelMsg::Auth { pass: share_code.pass_code.clone() })
                        .unwrap(),
                )
                .await
                .unwrap();
            }
            Some(TunnelMsg::AuthOk) => {
                eprintln!("[client] authenticated, requesting GET {path}");
                dc.send_text(
                    serde_json::to_string(&TunnelMsg::Req {
                        id: protocol::random_code(16),
                        method: "GET".into(),
                        path: path.clone(),
                        headers: Default::default(),
                        body: None,
                    })
                    .unwrap(),
                )
                .await
                .unwrap();
            }
            Some(TunnelMsg::AuthFail) => {
                eprintln!("[client] AUTH FAILED");
                std::process::exit(1);
            }
            Some(TunnelMsg::ResStart { status, .. }) => {
                eprintln!("[client] response: {status}");
            }
            Some(TunnelMsg::ResChunk { data, .. }) => {
                body.extend_from_slice(&B64.decode(data).unwrap());
            }
            Some(TunnelMsg::ResEnd { .. }) => {
                println!("{}", String::from_utf8_lossy(&body));
                eprintln!("[client] SUCCESS ({} bytes)", body.len());
                std::process::exit(0);
            }
            Some(TunnelMsg::ResErr { message, .. }) => {
                eprintln!("[client] response error: {message}");
                std::process::exit(1);
            }
            _ => {}
        }
    }
}

//! Minimal in-process loopback: two PeerConnections exchange SDP directly (no tracker), open a data channel, send one message.
//! Isolates ICE/DTLS/SCTP from all signaling code.

use std::sync::Arc;
use std::time::Duration;


use webrtc::data_channel::data_channel_message::DataChannelMessage;
use webrtc::data_channel::RTCDataChannel;
use webrtc::ice_transport::ice_server::RTCIceServer;
use webrtc::peer_connection::configuration::RTCConfiguration;
use webrtc::peer_connection::sdp::session_description::RTCSessionDescription;
use webrtc::peer_connection::RTCPeerConnection;

async fn build_pc() -> Arc<RTCPeerConnection> {
    let api = llama_server_connect::peer::build_api();
    Arc::new(
        api.new_peer_connection(RTCConfiguration {
            ice_servers: vec![RTCIceServer {
                urls: vec!["stun:stun.l.google.com:19302".to_string()],
                ..Default::default()
            }],
            ..Default::default()
        })
        .await
        .unwrap(),
    )
}

#[tokio::main]
async fn main() {
    env_logger::Builder::from_env(env_logger::Env::default().default_filter_or("info")).init();

    let offerer = build_pc().await;
    let answerer = build_pc().await;

    // answerer echoes whatever it receives
    answerer.on_data_channel(Box::new(|dc: Arc<RTCDataChannel>| {
        eprintln!("[answerer] got data channel");
        let dc2 = Arc::clone(&dc);
        dc.on_message(Box::new(move |m: DataChannelMessage| {
            let dc = Arc::clone(&dc2);
            Box::pin(async move {
                eprintln!("[answerer] got: {:?}", String::from_utf8_lossy(&m.data));
                dc.send_text("echo").await.unwrap();
            })
        }));
        Box::pin(async {})
    }));

    // offerer sends on open, exits on reply
    let dc = offerer.create_data_channel("tunnel", None).await.unwrap();
    let dc2 = Arc::clone(&dc);
    dc.on_open(Box::new(move || {
        let dc = Arc::clone(&dc2);
        Box::pin(async move {
            eprintln!("[offerer] channel open, sending");
            dc.send_text("hello over loopback").await.unwrap();
        })
    }));
    dc.on_message(Box::new(|m: DataChannelMessage| {
        eprintln!("[offerer] reply: {:?}", String::from_utf8_lossy(&m.data));
        eprintln!("LOOPBACK SUCCESS");
        std::process::exit(0);
    }));

    let offer = offerer.create_offer(None).await.unwrap();
    let mut gathered = offerer.gathering_complete_promise().await;
    offerer.set_local_description(offer).await.unwrap();
    let _ = tokio::time::timeout(Duration::from_secs(10), gathered.recv()).await;
    let offer_sdp = offerer.local_description().await.unwrap();

    answerer
        .set_remote_description(RTCSessionDescription::offer(offer_sdp.sdp).unwrap())
        .await
        .unwrap();
    let answer = answerer.create_answer(None).await.unwrap();
    let mut gathered = answerer.gathering_complete_promise().await;
    answerer.set_local_description(answer).await.unwrap();
    let _ = tokio::time::timeout(Duration::from_secs(10), gathered.recv()).await;
    let answer_sdp = answerer.local_description().await.unwrap();

    offerer
        .set_remote_description(RTCSessionDescription::answer(answer_sdp.sdp).unwrap())
        .await
        .unwrap();

    tokio::time::sleep(Duration::from_secs(30)).await;
    eprintln!("TIMEOUT - loopback failed");
    std::process::exit(1);
}

//! WebTorrent WebSocket tracker client (host side), wire-compatible with the webui's `Tracker` class in `webrtc-tunnel.ts` (llama.cpp branch `xsn/remote_server`).
//! The host announces with no offers to stay in the swarm; when a browser announces an offer, the tracker relays it to us and we send back a directed answer.

use std::sync::Arc;
use std::time::Duration;

use futures_util::{SinkExt, StreamExt};
use serde::{Deserialize, Serialize};
use tokio::sync::mpsc;
use tokio_tungstenite::connect_async;
use tokio_tungstenite::tungstenite::Message;

/// Public WebTorrent trackers used as the signaling rendezvous.
pub const DEFAULT_TRACKERS: &[&str] = &[
    "wss://tracker.openwebtorrent.com",
    "wss://tracker.webtorrent.dev",
];

/// Matches the UI's ANNOUNCE_INTERVAL_MS.
pub const ANNOUNCE_INTERVAL: Duration = Duration::from_secs(30);

#[derive(Serialize, Deserialize, Clone, Debug)]
pub struct SessionDesc {
    #[serde(rename = "type")]
    pub sdp_type: String,
    pub sdp: String,
}

/// Host keep-alive announce: `{action, info_hash, peer_id, numwant: 0}`.
#[derive(Serialize)]
struct HostAnnounce<'a> {
    action: &'static str,
    info_hash: &'a str,
    peer_id: &'a str,
    numwant: u32,
}

/// Directed answer to one browser's offer.
#[derive(Serialize)]
struct AnswerAnnounce<'a> {
    action: &'static str,
    info_hash: &'a str,
    peer_id: &'a str,
    to_peer_id: &'a str,
    offer_id: &'a str,
    answer: &'a SessionDesc,
}

/// Any message the tracker sends us.
#[derive(Deserialize, Debug)]
struct TrackerMsg {
    offer: Option<SessionDesc>,
    offer_id: Option<String>,
    peer_id: Option<String>,
    #[serde(rename = "failure reason")]
    failure_reason: Option<String>,
    #[serde(rename = "warning message")]
    warning_message: Option<String>,
}

/// Offer relayed by the tracker, plus a channel to send the answer back.
pub struct IncomingOffer {
    pub tracker_url: String,
    pub offer_sdp: String,
    pub offer_id: String,
    pub from_peer_id: String,
    pub reply: mpsc::UnboundedSender<OutgoingAnswer>,
}

pub struct OutgoingAnswer {
    pub to_peer_id: String,
    pub offer_id: String,
    pub answer_sdp: String,
}

#[derive(Clone)]
pub struct TrackerConfig {
    pub info_hash: String,
    pub peer_id: String,
}

/// Run one tracker connection forever, reconnecting with backoff. Relayed offers are delivered on `offers_tx`.
pub async fn run_tracker(
    url: String,
    cfg: Arc<TrackerConfig>,
    offers_tx: mpsc::UnboundedSender<IncomingOffer>,
) {
    let mut backoff = Duration::from_secs(5);
    loop {
        match tracker_session(&url, &cfg, &offers_tx).await {
            Ok(()) => backoff = Duration::from_secs(5),
            Err(e) => log::debug!("tracker {url}: {e}; reconnecting in {backoff:?}"),
        }
        tokio::time::sleep(backoff).await;
        backoff = (backoff * 2).min(Duration::from_secs(120));
    }
}

async fn tracker_session(
    url: &str,
    cfg: &TrackerConfig,
    offers_tx: &mpsc::UnboundedSender<IncomingOffer>,
) -> Result<(), String> {
    let connect = tokio::time::timeout(Duration::from_secs(10), connect_async(url));
    let (ws, _) = connect
        .await
        .map_err(|_| "connect timeout".to_string())?
        .map_err(|e| e.to_string())?;
    log::info!("tracker {url}: connected");
    let (mut sink, mut stream) = ws.split();

    let (reply_tx, mut reply_rx) = mpsc::unbounded_channel::<OutgoingAnswer>();

    let announce = serde_json::to_string(&HostAnnounce {
        action: "announce",
        info_hash: &cfg.info_hash,
        peer_id: &cfg.peer_id,
        numwant: 0,
    })
    .unwrap();
    sink.send(Message::text(announce.clone()))
        .await
        .map_err(|e| e.to_string())?;

    let mut ticker = tokio::time::interval(ANNOUNCE_INTERVAL);
    ticker.tick().await; // first tick fires immediately; we already announced

    loop {
        tokio::select! {
            _ = ticker.tick() => {
                sink.send(Message::text(announce.clone())).await.map_err(|e| e.to_string())?;
            }
            Some(ans) = reply_rx.recv() => {
                let msg = serde_json::to_string(&AnswerAnnounce {
                    action: "announce",
                    info_hash: &cfg.info_hash,
                    peer_id: &cfg.peer_id,
                    to_peer_id: &ans.to_peer_id,
                    offer_id: &ans.offer_id,
                    answer: &SessionDesc { sdp_type: "answer".into(), sdp: ans.answer_sdp },
                }).unwrap();
                sink.send(Message::text(msg)).await.map_err(|e| e.to_string())?;
                log::info!("tracker {url}: sent answer to peer {}", ans.to_peer_id);
            }
            frame = stream.next() => {
                let frame = match frame {
                    None => return Err("connection closed".into()),
                    Some(Err(e)) => return Err(e.to_string()),
                    Some(Ok(f)) => f,
                };
                let Message::Text(txt) = frame else { continue };
                let msg: TrackerMsg = match serde_json::from_str(&txt) {
                    Ok(m) => m,
                    Err(e) => { log::debug!("tracker {url}: unparseable message ({e}): {txt}"); continue }
                };
                if let Some(reason) = msg.failure_reason {
                    return Err(format!("tracker failure: {reason}"));
                }
                if let Some(w) = msg.warning_message {
                    log::warn!("tracker {url}: warning: {w}");
                }
                if let (Some(offer), Some(offer_id), Some(peer_id)) = (msg.offer, msg.offer_id, msg.peer_id) {
                    log::info!("tracker {url}: offer {offer_id} from peer {peer_id}");
                    let _ = offers_tx.send(IncomingOffer {
                        tracker_url: url.to_string(),
                        offer_sdp: offer.sdp,
                        offer_id,
                        from_peer_id: peer_id,
                        reply: reply_tx.clone(),
                    });
                }
            }
        }
    }
}

//! llama-connect: expose a local llama-server over WebRTC data channels, signaling via public WebTorrent trackers.
//! Protocol-compatible with the llama.cpp webui remote-access feature (PR #24577, branch `xsn/remote_server`); this binary replaces the "host browser" role.

pub mod peer;
pub mod protocol;
pub mod signaling;
pub mod tunnel;

use std::collections::{HashSet, VecDeque};
use std::sync::Arc;

use tokio::sync::mpsc;

/// Offer keys kept for dedup, oldest dropped first.
const MAX_SEEN_OFFERS: usize = 1024;

#[derive(Clone)]
pub struct Config {
    /// Local llama-server base URL, e.g. "http://127.0.0.1:8080".
    pub upstream: String,
    pub room_code: String,
    pub pass_code: String,
    pub trackers: Vec<String>,
    pub stun_servers: Vec<String>,
}

/// The host loop: announce on all trackers, answer every incoming browser offer.
pub async fn run_host(cfg: Config) {
    let tracker_cfg = Arc::new(signaling::TrackerConfig {
        info_hash: protocol::room_to_info_hash(&cfg.room_code),
        peer_id: protocol::random_code(20),
    });

    let (offers_tx, mut offers_rx) = mpsc::unbounded_channel::<signaling::IncomingOffer>();
    for url in &cfg.trackers {
        tokio::spawn(signaling::run_tracker(
            url.clone(),
            Arc::clone(&tracker_cfg),
            offers_tx.clone(),
        ));
    }

    let peer_cfg = Arc::new(peer::PeerConfig {
        stun_servers: cfg.stun_servers.clone(),
        upstream: cfg.upstream.clone(),
        pass_code: cfg.pass_code.clone(),
    });

    // multiple trackers can relay the same offer; answer each (peer, offer) only once
    let mut seen: HashSet<String> = Default::default();
    let mut order: VecDeque<String> = Default::default();
    while let Some(incoming) = offers_rx.recv().await {
        let dedup_key = format!("{}:{}", incoming.from_peer_id, incoming.offer_id);
        if !seen.insert(dedup_key.clone()) {
            continue;
        }
        order.push_back(dedup_key);
        if order.len() > MAX_SEEN_OFFERS
            && let Some(oldest) = order.pop_front()
        {
            seen.remove(&oldest);
        }
        let peer_cfg = Arc::clone(&peer_cfg);
        tokio::spawn(async move {
            match peer::answer_offer(&peer_cfg, incoming.offer_sdp).await {
                Ok(answer_sdp) => {
                    let _ = incoming.reply.send(signaling::OutgoingAnswer {
                        to_peer_id: incoming.from_peer_id,
                        offer_id: incoming.offer_id,
                        answer_sdp,
                    });
                }
                Err(e) => log::warn!("failed to answer offer: {e}"),
            }
        });
    }
}

//! WebRTC answerer built on webrtc-rs 0.17 (last release of the classic line; 0.20+ is a sans-IO rewrite that is not yet stable).
//! For each relayed offer: set the remote offer, create a non-trickle answer (all ICE candidates embedded in the SDP), then hand incoming data channels to the tunnel layer.

use std::sync::Arc;
use std::time::Duration;

use tokio::sync::watch;
use webrtc::api::setting_engine::SettingEngine;
use webrtc::api::{APIBuilder, API};
use webrtc::data_channel::RTCDataChannel;
use webrtc::ice_transport::ice_server::RTCIceServer;
use webrtc::peer_connection::configuration::RTCConfiguration;
use webrtc::peer_connection::peer_connection_state::RTCPeerConnectionState;
use webrtc::peer_connection::sdp::session_description::RTCSessionDescription;

use crate::tunnel;

/// Matches the UI's STUN_CONFIG.
pub const DEFAULT_STUN: &[&str] = &[
    "stun:stun.l.google.com:19302",
    "stun:stun1.l.google.com:19302",
];

/// Matches the UI's ICE_GATHER_TIMEOUT_MS.
const ICE_GATHER_TIMEOUT: Duration = Duration::from_secs(10);

pub struct PeerConfig {
    pub stun_servers: Vec<String>,
    /// Local llama-server base, e.g. "http://127.0.0.1:8080"
    pub upstream: String,
    pub pass_code: String,
}

/// With LSC_LOOPBACK_ICE=1, restrict ICE to loopback candidates.
/// This is a test mode for same-machine runs where a firewall drops inbound UDP on real interfaces (e.g. macOS Application Firewall).
pub fn build_api() -> API {
    let mut se = SettingEngine::default();
    // browsers hide host candidates behind mDNS (.local) names; resolve them
    se.set_ice_multicast_dns_mode(webrtc::ice::mdns::MulticastDnsMode::QueryOnly);
    if std::env::var("LSC_LOOPBACK_ICE").is_ok() {
        se.set_include_loopback_candidate(true);
        se.set_ip_filter(Box::new(|ip: std::net::IpAddr| ip.is_loopback()));
    }
    APIBuilder::new().with_setting_engine(se).build()
}

/// Answer a browser's offer and return the answer SDP with all ICE candidates embedded.
/// A spawned task owns the connection until it dies.
pub async fn answer_offer(cfg: &PeerConfig, offer_sdp: String) -> Result<String, String> {
    let api = build_api();
    let rtc_cfg = RTCConfiguration {
        ice_servers: vec![RTCIceServer {
            urls: cfg.stun_servers.clone(),
            ..Default::default()
        }],
        ..Default::default()
    };
    let pc = Arc::new(
        api.new_peer_connection(rtc_cfg)
            .await
            .map_err(|e| e.to_string())?,
    );

    let upstream = cfg.upstream.clone();
    let pass_code = cfg.pass_code.clone();
    pc.on_data_channel(Box::new(move |dc: Arc<RTCDataChannel>| {
        log::info!("data channel opened: {}", dc.label());
        tunnel::attach(dc, upstream.clone(), pass_code.clone());
        Box::pin(async {})
    }));

    let (dead_tx, mut dead_rx) = watch::channel(false);
    pc.on_peer_connection_state_change(Box::new(move |state: RTCPeerConnectionState| {
        log::info!("peer connection state: {state}");
        if matches!(
            state,
            RTCPeerConnectionState::Failed
                | RTCPeerConnectionState::Closed
                | RTCPeerConnectionState::Disconnected
        ) {
            let _ = dead_tx.send(true);
        }
        Box::pin(async {})
    }));

    let offer = RTCSessionDescription::offer(offer_sdp).map_err(|e| e.to_string())?;
    pc.set_remote_description(offer).await.map_err(|e| e.to_string())?;
    let answer = pc.create_answer(None).await.map_err(|e| e.to_string())?;

    // non-trickle: wait for gathering so the SDP has all candidates
    let mut gathered = pc.gathering_complete_promise().await;
    pc.set_local_description(answer).await.map_err(|e| e.to_string())?;
    let _ = tokio::time::timeout(ICE_GATHER_TIMEOUT, gathered.recv()).await;

    let local = pc
        .local_description()
        .await
        .ok_or_else(|| "no local description after gathering".to_string())?;

    // keep the connection alive until it dies
    tokio::spawn(async move {
        let _ = dead_rx.wait_for(|dead| *dead).await;
        log::info!("peer connection terminated");
        let _ = pc.close().await;
    });

    Ok(local.sdp)
}

//! Tunnel protocol shared with the webui (`tools/ui/src/lib/utils/webrtc-tunnel.ts` on branch `xsn/remote_server`). Keep in lockstep with the UI.
//! Share code (40 chars) = room code (8) + pass code (32).
//! The room code padded to 20 chars is the tracker info_hash; the pass code authenticates the client on the data channel.

use rand::Rng;
use serde::{Deserialize, Serialize};

/// Characters that are unambiguous to read aloud or type (matches the UI).
pub const CODE_CHARS: &[u8] = b"ABCDEFGHJKMNPQRSTUVWXYZabcdefghjkmnpqrstuvwxyz23456789";

pub const ROOM_CODE_LEN: usize = 8;
pub const PASS_CODE_LEN: usize = 32;

/// Max raw bytes per res_chunk message, before base64 (matches UI CHUNK_BYTES).
pub const CHUNK_BYTES: usize = 8192;

pub fn random_code(len: usize) -> String {
    let mut rng = rand::thread_rng();
    (0..len)
        .map(|_| CODE_CHARS[rng.gen_range(0..CODE_CHARS.len())] as char)
        .collect()
}

/// info_hash must be exactly 20 chars for WebTorrent trackers.
pub fn room_to_info_hash(room_code: &str) -> String {
    let mut s: String = room_code.chars().take(20).collect();
    while s.len() < 20 {
        s.push('0');
    }
    s
}

pub struct ShareCode {
    pub room_code: String,
    pub pass_code: String,
}

impl ShareCode {
    pub fn generate() -> Self {
        Self {
            room_code: random_code(ROOM_CODE_LEN),
            pass_code: random_code(PASS_CODE_LEN),
        }
    }

    /// Parse a 40-char share code (whitespace tolerated, as the UI strips it too).
    pub fn parse(code: &str) -> Result<Self, String> {
        let code: String = code.chars().filter(|c| !c.is_whitespace()).collect();
        if code.len() != ROOM_CODE_LEN + PASS_CODE_LEN {
            return Err(format!(
                "share code must be {} characters, got {}",
                ROOM_CODE_LEN + PASS_CODE_LEN,
                code.len()
            ));
        }
        Ok(Self {
            room_code: code[..ROOM_CODE_LEN].to_string(),
            pass_code: code[ROOM_CODE_LEN..].to_string(),
        })
    }

    pub fn as_string(&self) -> String {
        format!("{}{}", self.room_code, self.pass_code)
    }

    /// 8-char blocks for readability, like the UI displays it.
    pub fn display_blocks(&self) -> String {
        self.as_string()
            .as_bytes()
            .chunks(8)
            .map(|c| std::str::from_utf8(c).unwrap())
            .collect::<Vec<_>>()
            .join(" ")
    }
}

/// Messages exchanged over the RTCDataChannel (JSON text frames).
#[derive(Serialize, Deserialize, Debug)]
#[serde(tag = "type", rename_all = "snake_case")]
pub enum TunnelMsg {
    Auth {
        pass: String,
    },
    AuthOk,
    AuthFail,
    Req {
        id: String,
        method: String,
        path: String,
        headers: std::collections::HashMap<String, String>,
        body: Option<String>, // base64 or null
    },
    ResStart {
        id: String,
        status: u16,
        headers: std::collections::HashMap<String, String>,
    },
    ResChunk {
        id: String,
        data: String, // base64
    },
    ResEnd {
        id: String,
    },
    ResErr {
        id: String,
        message: String,
    },
    Cancel {
        id: String,
    },
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn share_code_roundtrip() {
        let sc = ShareCode::generate();
        let s = sc.as_string();
        assert_eq!(s.len(), 40);
        assert!(s.bytes().all(|b| CODE_CHARS.contains(&b)));
        let parsed = ShareCode::parse(&sc.display_blocks()).unwrap();
        assert_eq!(parsed.room_code, sc.room_code);
        assert_eq!(parsed.pass_code, sc.pass_code);
        assert!(ShareCode::parse("too-short").is_err());
    }

    #[test]
    fn info_hash_padding() {
        assert_eq!(room_to_info_hash("AbCd2345"), "AbCd2345000000000000");
        assert_eq!(room_to_info_hash("AbCd2345").len(), 20);
    }

    #[test]
    fn tunnel_msg_wire_format_matches_ui() {
        // tag names must match the TS literals exactly
        let m: TunnelMsg = serde_json::from_str(r#"{"type":"auth","pass":"x"}"#).unwrap();
        assert!(matches!(m, TunnelMsg::Auth { .. }));
        let m: TunnelMsg =
            serde_json::from_str(r#"{"type":"req","id":"1","method":"GET","path":"/health","headers":{},"body":null}"#)
                .unwrap();
        assert!(matches!(m, TunnelMsg::Req { .. }));
        assert_eq!(
            serde_json::to_string(&TunnelMsg::AuthOk).unwrap(),
            r#"{"type":"auth_ok"}"#
        );
        assert_eq!(
            serde_json::to_string(&TunnelMsg::ResEnd { id: "a".into() }).unwrap(),
            r#"{"type":"res_end","id":"a"}"#
        );
        assert_eq!(
            serde_json::to_string(&TunnelMsg::ResStart {
                id: "a".into(),
                status: 200,
                headers: Default::default()
            })
            .unwrap(),
            r#"{"type":"res_start","id":"a","status":200,"headers":{}}"#
        );
    }
}

import { browser } from '$app/environment';
import { ClientTunnel, HostTunnel, generatePassCode, generateRoomCode } from '$lib/utils/webrtc-tunnel';

// Stores the generated host codes; persists until explicitly regenerated.
const HOST_CODES_KEY = 'llama_webrtc_host_codes';
// Stores the active session (mode + codes) for auto-reconnect on reload.
const SESSION_KEY = 'llama_webrtc_session';

type HostCodes = { roomCode: string; passCode: string };
type SessionData = { mode: 'host' | 'client'; roomCode: string; passCode: string };
type ConnectionStatus = 'idle' | 'connecting' | 'connected' | 'error';

class WebRTCStore {
	mode = $state<'off' | 'host' | 'client'>('off');
	status = $state<ConnectionStatus>('idle');
	peerCount = $state(0);
	errorMessage = $state('');

	// Reflect the saved host codes; populated on init even when mode is 'off'.
	private _roomCode = $state('');
	private _passCode = $state('');

	private hostTunnel: HostTunnel | null = null;
	private clientTunnel: ClientTunnel | null = null;
	// Requests that arrive while mode='client' but tunnel not yet open are held here.
	private connectionWaiters: Array<{ resolve: () => void; reject: (e: Error) => void }> = [];
	// The original window.fetch saved before the interceptor is installed.
	private originalFetch: typeof window.fetch | null = null;

	constructor() {
		if (browser) {
			// Load persisted host codes so the UI can show them before host is enabled.
			const saved = this.readHostCodes();
			if (saved) {
				this._roomCode = saved.roomCode;
				this._passCode = saved.passCode;
			}
			this.restoreSession();
		}
	}

	get roomCode(): string {
		return this._roomCode;
	}

	get passCode(): string {
		return this._passCode;
	}

	// Full 40-char code shared with remote clients.
	get shareCode(): string {
		return this._roomCode + this._passCode;
	}

	get isConnected(): boolean {
		return this.status === 'connected';
	}

	get hasHostCodes(): boolean {
		return this._roomCode !== '' && this._passCode !== '';
	}

	// -------------------------------------------------------------------------
	// Host
	// -------------------------------------------------------------------------

	async startHost(): Promise<void> {
		if (this.mode !== 'off') return;

		// Reuse the persisted codes; generate once if none exist yet.
		let roomCode = this._roomCode;
		let passCode = this._passCode;

		if (!roomCode || !passCode) {
			roomCode = generateRoomCode();
			passCode = generatePassCode();
			this._roomCode = roomCode;
			this._passCode = passCode;
			this.writeHostCodes({ roomCode, passCode });
		}

		await this.activateHost(roomCode, passCode);
	}

	/** Generate a fresh room + pass code. Restarts the tunnel if currently active. */
	async regenerateCodes(): Promise<void> {
		const roomCode = generateRoomCode();
		const passCode = generatePassCode();
		this._roomCode = roomCode;
		this._passCode = passCode;
		this.writeHostCodes({ roomCode, passCode });

		if (this.mode === 'host') {
			this.hostTunnel?.stop();
			this.hostTunnel = null;
			await this.activateHost(roomCode, passCode);
		}
	}

	private async activateHost(roomCode: string, passCode: string): Promise<void> {
		this.mode = 'host';
		this.status = 'connecting';
		this.errorMessage = '';
		this.peerCount = 0;

		const tunnel = new HostTunnel(roomCode, passCode, {
			onPeerCountChange: (count) => {
				this.peerCount = count;
			}
		});

		try {
			await tunnel.start();
			this.hostTunnel = tunnel;
			this.status = 'connected';
			this.writeSession({ mode: 'host', roomCode, passCode });
		} catch (e) {
			this.hostTunnel = null;
			this.status = 'error';
			this.errorMessage = e instanceof Error ? e.message : String(e);
		}
	}

	stopHost(): void {
		this.hostTunnel?.stop();
		this.hostTunnel = null;
		this.mode = 'off';
		this.status = 'idle';
		this.peerCount = 0;
		// Codes are intentionally kept: _roomCode/_passCode and HOST_CODES_KEY
		// remain so the user can re-enable without a new code.
		this.clearSession();
	}

	// -------------------------------------------------------------------------
	// Client
	// -------------------------------------------------------------------------

	async joinAsClient(shareCode: string): Promise<void> {
		if (shareCode.length < 40) throw new Error('Invalid code: must be 40 characters');

		const roomCode = shareCode.slice(0, 8);
		const passCode = shareCode.slice(8);
		await this.activateClient(roomCode, passCode);
	}

	private async activateClient(roomCode: string, passCode: string): Promise<void> {
		this.mode = 'client';
		this.status = 'connecting';
		this.errorMessage = '';
		// Install the fetch interceptor synchronously (before any await) so that
		// requests fired by layout effects on the same tick are already captured.
		this.installInterceptor();

		const tunnel = new ClientTunnel(roomCode, passCode, {
			onConnected: () => {
				this.status = 'connected';
			},
			onDisconnected: () => {
				this.status = 'error';
				this.errorMessage = 'Disconnected from host';
			}
		});

		try {
			await tunnel.connect();
			this.clientTunnel = tunnel;
			this.writeSession({ mode: 'client', roomCode, passCode });
			// Release any requests that were queued while connecting.
			const waiters = this.connectionWaiters.splice(0);
			for (const w of waiters) w.resolve();
		} catch (e) {
			this.clientTunnel = null;
			this.mode = 'off';
			this.status = 'error';
			this.errorMessage = e instanceof Error ? e.message : String(e);
			this.uninstallInterceptor();
			// Reject queued requests.
			const waiters = this.connectionWaiters.splice(0);
			const err = e instanceof Error ? e : new Error(String(e));
			for (const w of waiters) w.reject(err);
			throw e;
		}
	}

	leaveAsClient(): void {
		this.uninstallInterceptor();
		this.clientTunnel?.disconnect();
		this.clientTunnel = null;
		this.mode = 'off';
		this.status = 'idle';
		this.clearSession();
	}

	// -------------------------------------------------------------------------
	// Fetch interceptor (installed synchronously when client mode activates)
	// -------------------------------------------------------------------------

	private installInterceptor(): void {
		if (this.originalFetch) return; // already installed
		this.originalFetch = window.fetch.bind(window);
		const store = this;
		window.fetch = function (input: RequestInfo | URL, init?: RequestInit) {
			try {
				const url =
					input instanceof Request
						? input.url
						: input instanceof URL
							? input.href
							: String(input);
				const parsed = new URL(url, window.location.href);
				if (parsed.origin === window.location.origin) {
					return store.tunnelFetch(input, init);
				}
			} catch {
				// not a parseable URL — fall through
			}
			return store.originalFetch!(input, init);
		};
	}

	private uninstallInterceptor(): void {
		if (!this.originalFetch) return;
		window.fetch = this.originalFetch;
		this.originalFetch = null;
	}

	// -------------------------------------------------------------------------
	// Fetch proxy
	// -------------------------------------------------------------------------

	tunnelFetch(input: RequestInfo | URL, init?: RequestInit): Promise<Response> {
		// If the tunnel is open, forward immediately.
		if (this.clientTunnel?.isConnected) {
			return this.clientTunnel.fetch(input, init);
		}
		// If we are still connecting, queue the request until the tunnel opens.
		if (this.mode === 'client' && this.status === 'connecting') {
			return new Promise<void>((resolve, reject) => {
				this.connectionWaiters.push({ resolve, reject });
			}).then(() => this.clientTunnel!.fetch(input, init));
		}
		throw new Error('tunnel not connected');
	}

	// -------------------------------------------------------------------------
	// Persistence helpers
	// -------------------------------------------------------------------------

	private readHostCodes(): HostCodes | null {
		try {
			const raw = localStorage.getItem(HOST_CODES_KEY);
			return raw ? (JSON.parse(raw) as HostCodes) : null;
		} catch {
			return null;
		}
	}

	private writeHostCodes(codes: HostCodes): void {
		localStorage.setItem(HOST_CODES_KEY, JSON.stringify(codes));
	}

	private restoreSession(): void {
		try {
			const raw = localStorage.getItem(SESSION_KEY);
			if (!raw) return;
			const session = JSON.parse(raw) as SessionData;
			if (session.mode === 'host') {
				void this.activateHost(session.roomCode, session.passCode);
			} else if (session.mode === 'client') {
				void this.activateClient(session.roomCode, session.passCode);
			}
		} catch {
			// ignore corrupt storage
		}
	}

	private writeSession(data: SessionData): void {
		localStorage.setItem(SESSION_KEY, JSON.stringify(data));
	}

	private clearSession(): void {
		localStorage.removeItem(SESSION_KEY);
	}
}

export const webrtcStore = new WebRTCStore();

//! Serves the "tunnel" data channel: pass-code auth, then HTTP forwarding to the local llama-server with streamed responses and client-initiated cancel.
//! Wire protocol: see `protocol.rs` and the webui's `webrtc-tunnel.ts`.

use std::collections::HashMap;
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::Arc;
use std::time::Duration;

use base64::engine::general_purpose::STANDARD as B64;
use base64::Engine;
use futures_util::StreamExt;
use tokio::sync::Mutex;
use webrtc::data_channel::data_channel_message::DataChannelMessage;
use webrtc::data_channel::RTCDataChannel;

use crate::protocol::{TunnelMsg, CHUNK_BYTES};

// hop-by-hop headers, not forwarded
const SKIP_REQ_HEADERS: &[&str] = &["host", "content-length", "connection", "accept-encoding"];
const SKIP_RES_HEADERS: &[&str] = &["transfer-encoding", "connection", "keep-alive"];

// response chunks pause while the send buffer sits above this mark
const BUFFER_HIGH_BYTES: usize = 1 << 20;
const DRAIN_POLL_INTERVAL: Duration = Duration::from_millis(10);

struct TunnelState {
    authenticated: AtomicBool,
    in_flight: Mutex<HashMap<String, tokio::task::JoinHandle<()>>>,
    http: reqwest::Client,
    upstream: String,
    pass_code: String,
}

/// Yield until the send buffer drains below the high water mark.
async fn wait_for_drain(dc: &Arc<RTCDataChannel>) {
    while dc.buffered_amount().await > BUFFER_HIGH_BYTES {
        tokio::time::sleep(DRAIN_POLL_INTERVAL).await;
    }
}

async fn send_msg(dc: &Arc<RTCDataChannel>, msg: &TunnelMsg) {
    if let Err(e) = dc.send_text(serde_json::to_string(msg).unwrap()).await {
        log::debug!("tunnel: send failed: {e}");
    }
}

/// Attach the tunnel protocol handlers to a newly-opened data channel.
pub fn attach(dc: Arc<RTCDataChannel>, upstream: String, pass_code: String) {
    let state = Arc::new(TunnelState {
        authenticated: AtomicBool::new(false),
        in_flight: Default::default(),
        http: reqwest::Client::new(),
        upstream,
        pass_code,
    });

    let msg_state = Arc::clone(&state);
    let msg_dc = Arc::clone(&dc);
    dc.on_message(Box::new(move |msg: DataChannelMessage| {
        let state = Arc::clone(&msg_state);
        let dc = Arc::clone(&msg_dc);
        Box::pin(async move { handle_message(dc, state, &msg.data).await })
    }));

    let close_state = Arc::clone(&state);
    dc.on_close(Box::new(move || {
        log::info!("tunnel: data channel closed");
        let state = Arc::clone(&close_state);
        Box::pin(async move {
            for (_, task) in state.in_flight.lock().await.drain() {
                task.abort();
            }
        })
    }));
}

async fn handle_message(dc: Arc<RTCDataChannel>, state: Arc<TunnelState>, data: &[u8]) {
    let msg: TunnelMsg = match serde_json::from_slice(data) {
        Ok(m) => m,
        Err(e) => {
            log::debug!("tunnel: malformed message: {e}");
            return;
        }
    };

    if !state.authenticated.load(Ordering::Acquire) {
        if let TunnelMsg::Auth { pass } = msg {
            if pass == state.pass_code {
                state.authenticated.store(true, Ordering::Release);
                log::info!("tunnel: client authenticated");
                send_msg(&dc, &TunnelMsg::AuthOk).await;
            } else {
                log::warn!("tunnel: client sent invalid pass code");
                send_msg(&dc, &TunnelMsg::AuthFail).await;
                let _ = dc.close().await;
            }
        }
        return;
    }

    match msg {
        TunnelMsg::Req { id, method, path, headers, body } => {
            let task = tokio::spawn(forward_request(
                Arc::clone(&dc),
                Arc::clone(&state),
                id.clone(),
                method,
                path,
                headers,
                body,
            ));
            state.in_flight.lock().await.insert(id, task);
        }
        TunnelMsg::Cancel { id } => {
            if let Some(task) = state.in_flight.lock().await.remove(&id) {
                log::info!("tunnel: request {id} cancelled by client");
                task.abort();
            }
        }
        _ => {}
    }
}

async fn forward_request(
    dc: Arc<RTCDataChannel>,
    state: Arc<TunnelState>,
    id: String,
    method: String,
    path: String,
    headers: HashMap<String, String>,
    body: Option<String>,
) {
    let started = std::time::Instant::now();
    let result = do_forward(&dc, &state, &id, &method, &path, headers, body).await;
    match result {
        Ok(status) => log::info!(
            "{method} {path} -> {status} ({} ms)",
            started.elapsed().as_millis()
        ),
        Err(e) => {
            log::warn!("{method} {path} -> error: {e}");
            send_msg(&dc, &TunnelMsg::ResErr { id: id.clone(), message: e }).await;
        }
    }
    state.in_flight.lock().await.remove(&id);
}

async fn do_forward(
    dc: &Arc<RTCDataChannel>,
    state: &TunnelState,
    id: &str,
    method: &str,
    path: &str,
    headers: HashMap<String, String>,
    body: Option<String>,
) -> Result<u16, String> {
    if !path.starts_with('/') {
        return Err("request path must be absolute".to_string());
    }

    let method = reqwest::Method::from_bytes(method.as_bytes()).map_err(|e| e.to_string())?;
    let url = format!("{}{}", state.upstream, path);

    let mut req = state.http.request(method, &url);
    for (k, v) in &headers {
        if SKIP_REQ_HEADERS.contains(&k.to_ascii_lowercase().as_str()) {
            continue;
        }
        req = req.header(k, v);
    }
    if let Some(b64) = body {
        let bytes = B64.decode(b64).map_err(|e| format!("bad request body: {e}"))?;
        req = req.body(bytes);
    }

    let res = req.send().await.map_err(|e| e.to_string())?;
    let status = res.status().as_u16();

    let mut res_headers = HashMap::new();
    for (k, v) in res.headers() {
        if SKIP_RES_HEADERS.contains(&k.as_str()) {
            continue;
        }
        if let Ok(v) = v.to_str() {
            res_headers.insert(k.to_string(), v.to_string());
        }
    }

    send_msg(
        dc,
        &TunnelMsg::ResStart { id: id.to_string(), status, headers: res_headers },
    )
    .await;

    let mut stream = res.bytes_stream();
    while let Some(chunk) = stream.next().await {
        let chunk = chunk.map_err(|e| e.to_string())?;
        for slice in chunk.chunks(CHUNK_BYTES) {
            wait_for_drain(dc).await;
            send_msg(
                dc,
                &TunnelMsg::ResChunk { id: id.to_string(), data: B64.encode(slice) },
            )
            .await;
        }
    }

    send_msg(dc, &TunnelMsg::ResEnd { id: id.to_string() }).await;
    Ok(status)
}

use llama_server_connect::{peer, protocol, signaling, run_host, Config};

const USAGE: &str = "\
llama-connect - expose a local llama-server remotely via WebRTC (P2P, no port forwarding)

Usage: llama-connect [OPTIONS]

Options:
  --port <PORT>      Port of the local llama-server (default: 8080)
  --host <HOST>      Host of the local llama-server (default: 127.0.0.1)
  --code <CODE>      Reuse an existing 40-char share code instead of generating one
  --tracker <URL>    WebTorrent tracker to announce on (repeatable; replaces defaults)
  --exit-on-stdin-eof
                     Exit as soon as stdin reaches EOF. Meant for a parent process
                     (ex: llama-server --connect) that spawns us with a stdin pipe:
                     the OS closes that pipe even when the parent is SIGKILLed, so
                     this is what keeps us from outliving a hard crash.
  -h, --help         Show this help
  --version          Show version
  --license          Show this program's license and the third-party license texts

The printed share code goes into the webui: Settings -> Remote Access -> join.
";

/// Our own license plus the notices of every crate we link against, baked into the binary so a
/// single downloaded executable carries the attributions those licenses require.
///
/// THIRD_PARTY_LICENSES.txt is generated by ./generate_thrid_party_licenses.sh; including it here
/// means a stale file fails the build only if it is missing, so re-run that script after changing
/// dependencies.
const LICENSES: &str = concat!(
    "llama-connect\n",
    "=============\n\n",
    include_str!("../LICENSE"),
    "\n",
    include_str!("../THIRD_PARTY_LICENSES.txt"),
);

struct Args {
    port: u16,
    host: String,
    code: Option<String>,
    trackers: Vec<String>,
    exit_on_stdin_eof: bool,
}

fn parse_args() -> Result<Args, String> {
    let mut args = Args {
        port: 8080,
        host: "127.0.0.1".to_string(),
        code: None,
        trackers: vec![],
        exit_on_stdin_eof: false,
    };
    let mut it = std::env::args().skip(1);
    while let Some(arg) = it.next() {
        let mut value = |name: &str| it.next().ok_or(format!("{name} requires a value"));
        match arg.as_str() {
            "--port" => {
                args.port = value("--port")?
                    .parse()
                    .map_err(|e| format!("invalid --port: {e}"))?;
            }
            "--host" => args.host = value("--host")?,
            "--code" => args.code = Some(value("--code")?),
            "--tracker" => args.trackers.push(value("--tracker")?),
            "--exit-on-stdin-eof" => args.exit_on_stdin_eof = true,
            "-h" | "--help" => {
                print!("{USAGE}");
                std::process::exit(0);
            }
            "--version" => {
                println!("llama-connect {}", env!("CARGO_PKG_VERSION"));
                std::process::exit(0);
            }
            "--license" => {
                use std::io::Write;
                // Straight to the raw handle: `print!` panics on the broken pipe that a
                // quarter-megabyte through `llama-connect --license | head` produces.
                let _ = std::io::stdout().write_all(LICENSES.as_bytes());
                std::process::exit(0);
            }
            other => return Err(format!("unknown argument: {other}\n\n{USAGE}")),
        }
    }
    if args.trackers.is_empty() {
        args.trackers = signaling::DEFAULT_TRACKERS.iter().map(|s| s.to_string()).collect();
    }
    Ok(args)
}

/// Exit when the parent process goes away.
///
/// The parent spawns us with a pipe on our stdin and holds the only write end. Whatever kills
/// the parent - clean exit, SIGKILL, segfault, power of the machine being pulled out from under
/// it - the kernel closes that end, and the read below returns 0. This is the only teardown
/// signal that survives a parent that never gets to run cleanup code, and unlike PR_SET_PDEATHSIG
/// (Linux-only) or job objects (Windows-only) it works the same way on all three platforms.
fn exit_on_stdin_eof() {
    std::thread::spawn(|| {
        use std::io::BufRead;
        let stdin = std::io::stdin();
        let mut lock = stdin.lock();
        loop {
            let mut line = String::new();
            match lock.read_line(&mut line) {
                Ok(0) => break,                  // EOF: parent is gone
                Ok(_) => {}                      // parent is alive; nothing is sent on this pipe yet
                Err(e) => {
                    log::warn!("stdin read failed, assuming the parent is gone: {e}");
                    break;
                }
            }
        }
        log::info!("stdin closed, parent process is gone - exiting");
        std::process::exit(1);
    });
}

async fn check_upstream(upstream: &str) {
    let url = format!("{upstream}/health");
    let client = reqwest::Client::builder()
        .timeout(std::time::Duration::from_secs(3))
        .build()
        .unwrap();
    match client.get(&url).send().await {
        Ok(res) if res.status().is_success() => {
            println!("  upstream   : {upstream} (llama-server is up)")
        }
        Ok(res) => println!("  upstream   : {upstream} (WARNING: /health returned {})", res.status()),
        Err(_) => println!(
            "  upstream   : {upstream} (WARNING: not reachable - start llama-server first)"
        ),
    }
}

fn main() {
    env_logger::Builder::from_env(env_logger::Env::default().default_filter_or("info"))
        .format(|buf, record| {
            use std::io::Write;
            writeln!(buf, "[{}] {}", record.level(), record.args())
        })
        .init();

    let args = match parse_args() {
        Ok(a) => a,
        Err(e) => {
            eprintln!("error: {e}");
            std::process::exit(1);
        }
    };

    if args.exit_on_stdin_eof {
        exit_on_stdin_eof();
    }

    let share_code = match &args.code {
        Some(code) => match protocol::ShareCode::parse(code) {
            Ok(sc) => sc,
            Err(e) => {
                eprintln!("error: {e}");
                std::process::exit(1);
            }
        },
        None => protocol::ShareCode::generate(),
    };

    let cfg = Config {
        upstream: format!("http://{}:{}", args.host, args.port),
        room_code: share_code.room_code.clone(),
        pass_code: share_code.pass_code.clone(),
        trackers: args.trackers.clone(),
        stun_servers: peer::DEFAULT_STUN.iter().map(|s| s.to_string()).collect(),
    };

    let rt = tokio::runtime::Runtime::new().expect("failed to create tokio runtime");
    rt.block_on(async {
        println!();
        println!("llama-connect {}", env!("CARGO_PKG_VERSION"));
        check_upstream(&cfg.upstream).await;
        println!("  trackers   : {}", cfg.trackers.join(", "));
        println!();
        println!("  Share code (enter in webui under Settings -> Remote Access):");
        println!();
        println!("      {}", share_code.display_blocks());
        println!();

        run_host(cfg).await;
    });
}

/**
 * WebRTC tunnel for remote llama.cpp access.
 *
 * Signaling uses the WebTorrent tracker WebSocket protocol (no external deps).
 * The room code is used as the info_hash rendezvous key; the pass code
 * authenticates the client on the data channel after the WebRTC handshake.
 *
 * Host:   announces periodically, accepts incoming offers, relays HTTP requests
 *         made by connected clients back to its own local server.
 * Client: sends an offer, authenticates via pass code, then all same-origin
 *         fetch calls are transparently forwarded through the data channel.
 */

const STUN_CONFIG: RTCConfiguration = {
	iceServers: [
		{ urls: 'stun:stun.l.google.com:19302' },
		{ urls: 'stun:stun1.l.google.com:19302' }
	]
};

const TRACKER_URLS = [
	'wss://tracker.openwebtorrent.com',
	'wss://tracker.btorrent.xyz'
];

const ICE_GATHER_TIMEOUT_MS = 10_000;
const ANNOUNCE_INTERVAL_MS = 30_000;
const CONNECT_TIMEOUT_MS = 30_000;
const TRACKER_CONNECT_TIMEOUT_MS = 10_000;

// Characters that are unambiguous to read aloud or type
const CODE_CHARS = 'ABCDEFGHJKMNPQRSTUVWXYZabcdefghjkmnpqrstuvwxyz23456789';

function randomStr(len: number): string {
	const bytes = new Uint8Array(len);
	crypto.getRandomValues(bytes);
	let result = '';
	for (const b of bytes) result += CODE_CHARS[b % CODE_CHARS.length];
	return result;
}

export function generateRoomCode(): string {
	return randomStr(8);
}

export function generatePassCode(): string {
	return randomStr(32);
}

// info_hash must be exactly 20 chars for WebTorrent trackers
function roomToInfoHash(roomCode: string): string {
	return roomCode.padEnd(20, '0').slice(0, 20);
}

function waitForIceComplete(pc: RTCPeerConnection): Promise<void> {
	return new Promise((resolve, reject) => {
		if (pc.iceGatheringState === 'complete') {
			resolve();
			return;
		}
		const timer = setTimeout(
			() => reject(new Error('ICE gathering timed out')),
			ICE_GATHER_TIMEOUT_MS
		);
		pc.addEventListener('icegatheringstatechange', () => {
			if (pc.iceGatheringState === 'complete') {
				clearTimeout(timer);
				resolve();
			}
		});
	});
}

// ---------------------------------------------------------------------------
// Tracker signaling (WebTorrent WS tracker protocol)
// ---------------------------------------------------------------------------

type TrackerMsg = Record<string, unknown>;

class Tracker {
	private ws: WebSocket | null = null;
	private readonly infoHash: string;
	private readonly peerId: string;

	onOffer?: (fromPeerId: string, offerId: string, offer: RTCSessionDescriptionInit) => void;
	onAnswer?: (offerId: string, answer: RTCSessionDescriptionInit) => void;
	onClose?: () => void;

	constructor(infoHash: string, peerId: string) {
		this.infoHash = infoHash;
		this.peerId = peerId;
	}

	connect(url: string): Promise<void> {
		return new Promise((resolve, reject) => {
			const ws = new WebSocket(url);
			this.ws = ws;
			const timer = setTimeout(
				() => reject(new Error('tracker connect timeout')),
				TRACKER_CONNECT_TIMEOUT_MS
			);

			ws.onopen = () => {
				clearTimeout(timer);
				resolve();
			};
			ws.onerror = () => {
				clearTimeout(timer);
				reject(new Error('tracker WebSocket error'));
			};
			ws.onclose = () => {
				this.onClose?.();
			};
			ws.onmessage = (event) => {
				try {
					const msg = JSON.parse(event.data as string) as TrackerMsg;
					if (msg.offer && msg.peer_id && msg.offer_id) {
						this.onOffer?.(
							msg.peer_id as string,
							msg.offer_id as string,
							msg.offer as RTCSessionDescriptionInit
						);
					} else if (msg.answer && msg.offer_id) {
						this.onAnswer?.(msg.offer_id as string, msg.answer as RTCSessionDescriptionInit);
					}
				} catch {
					// ignore malformed tracker messages
				}
			};
		});
	}

	private send(msg: TrackerMsg): void {
		if (this.ws?.readyState === WebSocket.OPEN) {
			this.ws.send(JSON.stringify(msg));
		}
	}

	announce(opts: {
		numwant?: number;
		offers?: Array<{ offer_id: string; offer: RTCSessionDescriptionInit }>;
	} = {}): void {
		const msg: TrackerMsg = {
			action: 'announce',
			info_hash: this.infoHash,
			peer_id: this.peerId,
			numwant: opts.numwant ?? 0
		};
		if (opts.offers) msg.offers = opts.offers;
		this.send(msg);
	}

	sendAnswer(toPeerId: string, offerId: string, answer: RTCSessionDescriptionInit): void {
		this.send({
			action: 'announce',
			info_hash: this.infoHash,
			peer_id: this.peerId,
			to_peer_id: toPeerId,
			answer,
			offer_id: offerId
		});
	}

	close(): void {
		this.ws?.close();
		this.ws = null;
	}
}

// ---------------------------------------------------------------------------
// Tunnel message types (JSON, sent over RTCDataChannel)
// ---------------------------------------------------------------------------

interface ReqMsg {
	type: 'req';
	id: string;
	method: string;
	path: string;
	headers: Record<string, string>;
	body: string | null; // base64 or null
}
interface ResStartMsg {
	type: 'res_start';
	id: string;
	status: number;
	headers: Record<string, string>;
}
interface ResChunkMsg {
	type: 'res_chunk';
	id: string;
	data: string; // base64
}
interface ResEndMsg {
	type: 'res_end';
	id: string;
}
interface ResErrMsg {
	type: 'res_err';
	id: string;
	message: string;
}
interface CancelMsg {
	type: 'cancel';
	id: string;
}
interface AuthMsg {
	type: 'auth';
	pass: string;
}
interface AuthOkMsg {
	type: 'auth_ok';
}
interface AuthFailMsg {
	type: 'auth_fail';
}

type TunnelMsg =
	| ReqMsg
	| ResStartMsg
	| ResChunkMsg
	| ResEndMsg
	| ResErrMsg
	| CancelMsg
	| AuthMsg
	| AuthOkMsg
	| AuthFailMsg;

// Max bytes per res_chunk message (keeps data channel messages well below limits)
const CHUNK_BYTES = 8192;

function uint8ToBase64(bytes: Uint8Array): string {
	let binary = '';
	for (let i = 0; i < bytes.length; i++) binary += String.fromCharCode(bytes[i]);
	return btoa(binary);
}

function base64ToUint8(b64: string): Uint8Array {
	return Uint8Array.from(atob(b64), (c) => c.charCodeAt(0));
}

// ---------------------------------------------------------------------------
// HostTunnel
// ---------------------------------------------------------------------------

export type HostCallbacks = {
	onPeerCountChange?: (count: number) => void;
};

export class HostTunnel {
	private readonly passCode: string;
	private readonly infoHash: string;
	private readonly peerId: string;
	private readonly callbacks: HostCallbacks;

	private trackers: Tracker[] = [];
	private peers = new Map<string, { pc: RTCPeerConnection; channel: RTCDataChannel }>();
	// AbortControllers for in-flight host-side fetch() calls, keyed by request id.
	private activeRequests = new Map<string, AbortController>();
	private announceTimer: ReturnType<typeof setInterval> | null = null;
	private stopped = false;

	constructor(roomCode: string, passCode: string, callbacks: HostCallbacks = {}) {
		this.passCode = passCode;
		this.infoHash = roomToInfoHash(roomCode);
		this.peerId = randomStr(20);
		this.callbacks = callbacks;
	}

	get peerCount(): number {
		return this.peers.size;
	}

	async start(): Promise<void> {
		await this.connectTrackers();
		this.announceTimer = setInterval(() => {
			for (const t of this.trackers) t.announce({ numwant: 0 });
		}, ANNOUNCE_INTERVAL_MS);
	}

	private async connectTrackers(): Promise<void> {
		for (const url of TRACKER_URLS) {
			try {
				await this.connectOneTracker(url);
			} catch {
				// try next
			}
		}
	}

	private async connectOneTracker(url: string): Promise<void> {
		const tracker = new Tracker(this.infoHash, this.peerId);
		tracker.onOffer = (fromPeerId, offerId, offer) => {
			void this.handleOffer(tracker, fromPeerId, offerId, offer);
		};
		tracker.onClose = () => {
			this.trackers = this.trackers.filter((t) => t !== tracker);
			if (!this.stopped) {
				setTimeout(() => void this.connectOneTracker(url), 5000);
			}
		};
		await tracker.connect(url);
		tracker.announce({ numwant: 0 });
		this.trackers.push(tracker);
	}

	private async handleOffer(
		tracker: Tracker,
		fromPeerId: string,
		offerId: string,
		offer: RTCSessionDescriptionInit
	): Promise<void> {
		try {
			const pc = new RTCPeerConnection(STUN_CONFIG);
			await pc.setRemoteDescription(new RTCSessionDescription(offer));
			const answer = await pc.createAnswer();
			await pc.setLocalDescription(answer);
			await waitForIceComplete(pc);
			tracker.sendAnswer(fromPeerId, offerId, pc.localDescription!);

			pc.ondatachannel = (event) => this.setupChannel(pc, fromPeerId, event.channel);
		} catch {
			// ignore failed handshakes
		}
	}

	private setupChannel(pc: RTCPeerConnection, peerId: string, channel: RTCDataChannel): void {
		let authenticated = false;

		channel.onclose = () => {
			if (this.peers.has(peerId)) {
				this.peers.delete(peerId);
				this.callbacks.onPeerCountChange?.(this.peers.size);
			}
			pc.close();
		};

		channel.onmessage = (event) => {
			try {
				const msg = JSON.parse(event.data as string) as TunnelMsg;

				if (!authenticated) {
					if (msg.type === 'auth') {
						if (msg.pass === this.passCode) {
							authenticated = true;
							channel.send(JSON.stringify({ type: 'auth_ok' } satisfies AuthOkMsg));
							this.peers.set(peerId, { pc, channel });
							this.callbacks.onPeerCountChange?.(this.peers.size);
						} else {
							channel.send(JSON.stringify({ type: 'auth_fail' } satisfies AuthFailMsg));
							channel.close();
						}
					}
					return;
				}

				if (msg.type === 'req') {
					void this.handleRequest(channel, msg);
				} else if (msg.type === 'cancel') {
					this.activeRequests.get(msg.id)?.abort();
				}
			} catch {
				// ignore malformed messages
			}
		};
	}

	private async handleRequest(channel: RTCDataChannel, msg: ReqMsg): Promise<void> {
		const { id, method, path, headers, body } = msg;
		const t0 = performance.now();
		const ac = new AbortController();
		this.activeRequests.set(id, ac);

		try {
			const init: RequestInit = { method, headers, signal: ac.signal };
			if (body !== null) init.body = base64ToUint8(body).buffer as ArrayBuffer;

			const response = await fetch(path, init);

			const resHeaders: Record<string, string> = {};
			response.headers.forEach((v, k) => {
				resHeaders[k] = v;
			});

			console.log(`[rtc] ${method} ${path} -> ${response.status} (${Math.round(performance.now() - t0)}ms)`);

			channel.send(
				JSON.stringify({
					type: 'res_start',
					id,
					status: response.status,
					headers: resHeaders
				} satisfies ResStartMsg)
			);

			const reader = response.body?.getReader();
			if (reader) {
				while (true) {
					const { done, value } = await reader.read();
					if (done) break;
					for (let i = 0; i < value.length; i += CHUNK_BYTES) {
						const slice = value.subarray(i, i + CHUNK_BYTES);
						channel.send(
							JSON.stringify({
								type: 'res_chunk',
								id,
								data: uint8ToBase64(slice)
							} satisfies ResChunkMsg)
						);
					}
				}
			}

			channel.send(JSON.stringify({ type: 'res_end', id } satisfies ResEndMsg));
		} catch (e) {
			// AbortError means the client cancelled — no need to send an error back.
			if (!(e instanceof DOMException && e.name === 'AbortError')) {
				const errMsg = e instanceof Error ? e.message : String(e);
				console.error(`[rtc] ${method} ${path} -> error: ${errMsg}`);
				channel.send(
					JSON.stringify({ type: 'res_err', id, message: errMsg } satisfies ResErrMsg)
				);
			}
		} finally {
			this.activeRequests.delete(id);
		}
	}

	stop(): void {
		this.stopped = true;
		if (this.announceTimer) clearInterval(this.announceTimer);
		for (const t of this.trackers) t.close();
		for (const { pc, channel } of this.peers.values()) {
			channel.close();
			pc.close();
		}
		for (const ac of this.activeRequests.values()) ac.abort();
		this.trackers = [];
		this.peers.clear();
		this.activeRequests.clear();
	}
}

// ---------------------------------------------------------------------------
// ClientTunnel
// ---------------------------------------------------------------------------

export type ClientCallbacks = {
	onConnected?: () => void;
	onDisconnected?: () => void;
};

type PendingReq = {
	onStart: (status: number, headers: Record<string, string>) => void;
	onChunk: (data: string) => void;
	onEnd: () => void;
	onError: (message: string) => void;
};

export class ClientTunnel {
	private readonly passCode: string;
	private readonly infoHash: string;
	private readonly peerId: string;
	private readonly callbacks: ClientCallbacks;

	private pc: RTCPeerConnection | null = null;
	private channel: RTCDataChannel | null = null;
	private tracker: Tracker | null = null;
	private pending = new Map<string, PendingReq>();

	constructor(roomCode: string, passCode: string, callbacks: ClientCallbacks = {}) {
		this.passCode = passCode;
		this.infoHash = roomToInfoHash(roomCode);
		this.peerId = randomStr(20);
		this.callbacks = callbacks;
	}

	get isConnected(): boolean {
		return this.channel?.readyState === 'open';
	}

	async connect(): Promise<void> {
		let lastError: Error = new Error('no trackers available');
		for (const url of TRACKER_URLS) {
			try {
				await this.connectViaTracker(url);
				return;
			} catch (e) {
				lastError = e instanceof Error ? e : new Error(String(e));
				this.cleanupConnection();
			}
		}
		throw lastError;
	}

	private async connectViaTracker(trackerUrl: string): Promise<void> {
		const offerId = randomStr(20);
		const pc = new RTCPeerConnection(STUN_CONFIG);
		this.pc = pc;

		const channel = pc.createDataChannel('tunnel', { ordered: true });
		this.channel = channel;

		const offer = await pc.createOffer();
		await pc.setLocalDescription(offer);
		await waitForIceComplete(pc);

		const tracker = new Tracker(this.infoHash, this.peerId);
		this.tracker = tracker;
		await tracker.connect(trackerUrl);

		return new Promise((resolve, reject) => {
			const timer = setTimeout(() => {
				reject(new Error('connection timed out waiting for host'));
			}, CONNECT_TIMEOUT_MS);

			tracker.onAnswer = async (_offerId, answer) => {
				if (_offerId !== offerId) return;
				try {
					await pc.setRemoteDescription(new RTCSessionDescription(answer));
				} catch (e) {
					clearTimeout(timer);
					reject(e);
				}
			};

			channel.onopen = () => {
				channel.send(JSON.stringify({ type: 'auth', pass: this.passCode } satisfies AuthMsg));
			};

			channel.onmessage = (event) => {
				try {
					const msg = JSON.parse(event.data as string) as TunnelMsg;
					if (msg.type === 'auth_ok') {
						clearTimeout(timer);
						this.callbacks.onConnected?.();
						resolve();
					} else if (msg.type === 'auth_fail') {
						clearTimeout(timer);
						reject(new Error('authentication failed: invalid passcode'));
					} else {
						this.routeResponseMsg(msg);
					}
				} catch {
					// ignore
				}
			};

			channel.onclose = () => {
				this.callbacks.onDisconnected?.();
				this.rejectAllPending('connection closed');
			};

			channel.onerror = () => {
				clearTimeout(timer);
				reject(new Error('data channel error'));
			};

			tracker.announce({
				numwant: 1,
				offers: [{ offer_id: offerId, offer: pc.localDescription! }]
			});
		});
	}

	private routeResponseMsg(msg: TunnelMsg): void {
		if (
			msg.type !== 'res_start' &&
			msg.type !== 'res_chunk' &&
			msg.type !== 'res_end' &&
			msg.type !== 'res_err'
		)
			return;
		const req = this.pending.get(msg.id);
		if (!req) return;

		if (msg.type === 'res_start') {
			req.onStart(msg.status, msg.headers);
		} else if (msg.type === 'res_chunk') {
			req.onChunk(msg.data);
		} else if (msg.type === 'res_end') {
			req.onEnd();
			this.pending.delete(msg.id);
		} else if (msg.type === 'res_err') {
			req.onError(msg.message);
			this.pending.delete(msg.id);
		}
	}

	private rejectAllPending(reason: string): void {
		for (const req of this.pending.values()) req.onError(reason);
		this.pending.clear();
	}

	private cleanupConnection(): void {
		this.channel?.close();
		this.pc?.close();
		this.tracker?.close();
		this.channel = null;
		this.pc = null;
		this.tracker = null;
	}

	async fetch(input: RequestInfo | URL, init?: RequestInit): Promise<Response> {
		if (!this.channel || this.channel.readyState !== 'open') {
			throw new Error('tunnel not connected');
		}

		const request = new Request(input, init);
		const signal = init?.signal ?? (input instanceof Request ? input.signal : undefined);
		const id = randomStr(16);

		if (signal?.aborted) {
			return Promise.reject(new DOMException('Aborted', 'AbortError'));
		}

		// Extract path+query so the host fetches relative to its own origin
		const reqUrl = new URL(request.url);
		const path = reqUrl.pathname + reqUrl.search;

		const headers: Record<string, string> = {};
		request.headers.forEach((v, k) => {
			headers[k] = v;
		});

		let bodyB64: string | null = null;
		const bodyBytes = await request.arrayBuffer();
		if (bodyBytes.byteLength > 0) {
			bodyB64 = uint8ToBase64(new Uint8Array(bodyBytes));
		}

		return new Promise((resolve, reject) => {
			let streamController!: ReadableStreamDefaultController<Uint8Array>;
			const stream = new ReadableStream<Uint8Array>({
				start(ctrl) {
					streamController = ctrl;
				}
			});

			const abortHandler = () => {
				this.pending.delete(id);
				try {
					streamController.error(new DOMException('Aborted', 'AbortError'));
				} catch {
					// stream may already be closed
				}
				reject(new DOMException('Aborted', 'AbortError'));
				// Tell the host to stop the in-flight fetch
				if (this.channel?.readyState === 'open') {
					this.channel.send(JSON.stringify({ type: 'cancel', id } satisfies CancelMsg));
				}
			};

			signal?.addEventListener('abort', abortHandler, { once: true });

			this.pending.set(id, {
				onStart: (status, resHeaders) => {
					resolve(new Response(stream, { status, headers: resHeaders }));
				},
				onChunk: (data) => {
					streamController.enqueue(base64ToUint8(data));
				},
				onEnd: () => {
					signal?.removeEventListener('abort', abortHandler);
					streamController.close();
				},
				onError: (message) => {
					signal?.removeEventListener('abort', abortHandler);
					try {
						streamController.error(new Error(message));
					} catch {
						// stream may already be closed
					}
					reject(new Error(message));
					this.pending.delete(id);
				}
			});

			this.channel!.send(
				JSON.stringify({
					type: 'req',
					id,
					method: request.method,
					path,
					headers,
					body: bodyB64
				} satisfies ReqMsg)
			);
		});
	}

	disconnect(): void {
		this.rejectAllPending('disconnected');
		this.cleanupConnection();
	}
}
